326	    if (val) {
327	        /* Update the access time for the ageing algorithm.
328	         * Don't do it if we have a saving child, as this will trigger
329	         * a copy on write madness. */
330	        if (((flags & LOOKUP_NOTOUCH) == 0) &&
331	            (server.current_client && server.current_client->flags & CLIENT_NO_TOUCH) &&
332	            (server.executing_client && server.executing_client->cmd->proc != touchCommand))
333	            flags |= LOOKUP_NOTOUCH;
